import * as React from "react";
import { ResolvedTokens, useSelected } from "./brand";
import {
  Controls,
  Description,
  DocsContext,
  Primary,
  Stories,
  Subtitle,
  Title,
} from "@storybook/addon-docs/blocks";

// Every component manifest, keyed by file path. Generated by `npm run manifests:build`,
// so this page never has hand-typed component facts.
const manifests = import.meta.glob("../../manifests/components/*.json", {
  eager: true,
  import: "default",
}) as Record<string, Manifest>;

type Manifest = {
  name: string;
  title: string;
  description?: string;
  rationale?: string;
  install?: { command: string; dependencies?: string[] };
  figma?: { fileKey: string; nodeId: string };
  usage?: { do?: string[]; dont?: string[] };
  a11y?: string[];
  boundaries?: string[];
  whenToUseInstead?: { component: string; when: string }[];
  variants?: { axes?: Record<string, { default?: string; values: string[] }> };
  tokens?: { layer3?: string[] };
  source?: string;
};

const byName = Object.fromEntries(Object.values(manifests).map((m) => [m.name, m]));

const rule = { borderTop: "1px solid color-mix(in srgb, currentColor 15%, transparent)" };
const card = {
  border: "1px solid color-mix(in srgb, currentColor 15%, transparent)",
  borderRadius: 6,
  padding: "4px 16px",
};
const chip = {
  border: "1px solid color-mix(in srgb, currentColor 15%, transparent)",
  borderRadius: 4,
  padding: "1px 6px",
  fontSize: 12,
  background: "color-mix(in srgb, currentColor 5%, transparent)",
};
// Do and Don't cards take their color from the status tokens, so they follow the brand and scheme.
const tone = (kind: "success" | "error") => ({
  ...card,
  background: `var(--ds-color-status-${kind}-bg)`,
  borderColor: `var(--ds-color-status-${kind}-border)`,
});
const toneHeading = (kind: "success" | "error") => ({
  display: "flex",
  alignItems: "center",
  gap: 8,
  color: `var(--ds-color-status-${kind}-foreground)`,
});

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section style={{ marginTop: 32 }}>
      <h2 style={{ marginBottom: 8 }}>{title}</h2>
      {children}
    </section>
  );
}

function List({ items }: { items: string[] }) {
  return (
    <ul style={{ paddingLeft: 20 }}>
      {items.map((item) => (
        <li key={item} style={{ marginBottom: 4 }}>
          {item}
        </li>
      ))}
    </ul>
  );
}

function useManifest(): Manifest | undefined {
  const context = React.useContext(DocsContext);
  // Storybook records the CSF file path on every story as parameters.fileName.
  const importPath = String(context.componentStories()[0]?.parameters?.fileName ?? "");
  const file = importPath.split("/").pop()?.replace(".stories.tsx", "");
  return file ? byName[file] : undefined;
}

export function ComponentDocsPage() {
  const m = useManifest();
  const axes = Object.entries(m?.variants?.axes ?? {});
  const tokens = m?.tokens?.layer3 ?? [];
  const selected = useSelected();

  return (
    <>
      <Title />
      <Subtitle />
      <Description />
      {m && (
        <p style={{ display: "flex", flexWrap: "wrap", gap: 16, fontSize: 13 }}>
          {m.install && <code>{m.install.command}</code>}
          {m.figma && (
            <a
              href={`https://www.figma.com/design/${m.figma.fileKey}?node-id=${m.figma.nodeId.replace(":", "-")}`}
              target="_blank"
              rel="noreferrer"
            >
              Open in Figma
            </a>
          )}
        </p>
      )}
      <Primary />
      <Controls />

      {m?.whenToUseInstead && m.whenToUseInstead.length > 0 && (
        <Section title="Use something else when">
          <ul style={{ paddingLeft: 20 }}>
            {m.whenToUseInstead.map((row) => (
              <li key={row.component}>
                <code>{row.component}</code> — {row.when}
              </li>
            ))}
          </ul>
        </Section>
      )}

      {m?.usage && (
        <Section title="Do and don't">
          <div
            style={{
              display: "grid",
              gap: 16,
              gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
            }}
          >
            <div style={tone("success")}>
              <h3 style={toneHeading("success")}>
                <span aria-hidden>✓</span> Do
              </h3>
              <List items={m.usage.do ?? []} />
            </div>
            <div style={tone("error")}>
              <h3 style={toneHeading("error")}>
                <span aria-hidden>✕</span> Don&apos;t
              </h3>
              <List items={m.usage.dont ?? []} />
            </div>
          </div>
        </Section>
      )}

      {axes.length > 0 && (
        <Section title="Variant axes">
          <table style={{ width: "100%" }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left" }}>Prop</th>
                <th style={{ textAlign: "left" }}>Values</th>
                <th style={{ textAlign: "left" }}>Default</th>
              </tr>
            </thead>
            <tbody>
              {axes.map(([axis, def]) => (
                <tr key={axis}>
                  <td>
                    <code>{axis}</code>
                  </td>
                  <td>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                      {def.values.map((v) => (
                        <code key={v} style={chip}>
                          {v}
                        </code>
                      ))}
                    </div>
                  </td>
                  <td>
                    <code>{def.default}</code>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </Section>
      )}

      {m?.a11y && m.a11y.length > 0 && (
        <Section title="Accessibility">
          <List items={m.a11y} />
        </Section>
      )}

      {m?.boundaries && m.boundaries.length > 0 && (
        <Section title="Good to know">
          <List items={m.boundaries} />
        </Section>
      )}

      <Stories />

      {tokens.length > 0 && (
        <Section title="Tokens">
          <details style={rule}>
            <summary style={{ cursor: "pointer", padding: "8px 0" }}>
              {tokens.length} component tokens (layer 3), values for {selected.brand}{" "}
              {selected.scheme}
            </summary>
            <ResolvedTokens tokens={tokens} columns={2} />
          </details>
        </Section>
      )}
    </>
  );
}
